package com.campusconnect.campusconnect.controller;
import com.campusconnect.campusconnect.entity.*; import com.campusconnect.campusconnect.repository.*; import jakarta.servlet.http.HttpSession; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/blocks") public class BlockController { private final BlockRepository blocks; private final UserRepository users; public BlockController(BlockRepository b,UserRepository u){blocks=b;users=u;} private Long me(HttpSession s){Object x=s.getAttribute("userId");if(x==null)throw new IllegalArgumentException("Log in first");return ((Number)x).longValue();} @GetMapping("/{id}") public Map<String,Object> status(@PathVariable Long id,HttpSession s){Long m=me(s);return Map.of("blocked",blocks.existsByBlocker_IdAndBlocked_Id(m,id));} @PostMapping("/{id}") public Map<String,Object> toggle(@PathVariable Long id,HttpSession s){Long m=me(s);if(m.equals(id))throw new IllegalArgumentException("You cannot block yourself");User a=users.findById(m).orElseThrow(),b=users.findById(id).orElseThrow();var ex=blocks.findByBlocker_IdAndBlocked_Id(m,id);if(ex.isPresent()){blocks.delete(ex.get());return Map.of("blocked",false);}Block x=new Block();x.setBlocker(a);x.setBlocked(b);blocks.save(x);return Map.of("blocked",true);} }